\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:33:"Date in the form of MM (01 - 12).";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:8:"argument";a:2:{s:5:"field";s:7:"changed";s:2:"id";s:10:"date_month";}}s:11:"changed_day";a:3:{s:5:"title";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:11:"Updated day";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"help";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:33:"Date in the form of DD (01 - 31).";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:8:"argument";a:2:{s:5:"field";s:7:"changed";s:2:"id";s:8:"date_day";}}s:12:"changed_week";a:3:{s:5:"title";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:12:"Updated week";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"help";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:33:"Date in the form of WW (01 - 53).";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:8:"argument";a:2:{s:5:"field";s:7:"changed";s:2:"id";s:9:"date_week";}}}	-1	1772814851.178	1	config:core.extension views_data	3
